CREATE TABLE HistoricalFinancialStatements (
      id INTEGER PRIMARY KEY AUTOINCREMENT,
      symbol TEXT NOT NULL,
      statement_type TEXT DEFAULT 'ANNUAL',
      period_label TEXT NOT NULL,
